    PRIMARY KEY(day, channel));
CREATE TABLE release_calendar(os VARCHAR, version VARCHAR, released_at TIMESTAMPTZ);
CREATE TABLE source_watermarks(source VARCHAR PRIMARY KEY, complete_before TIMESTAMPTZ);

